import type { TaskItem } from '../types';

/**
 * Small dependency-free helpers shared by the task matrix (data/initialClients.ts)
 * and the task store (utils/taskStore.ts). Kept in their own module to avoid a circular import.
 */

/** Task numbers generated by the task matrix look like "W1-ACC-01-M1", "M-ACC-01-M2", "W2-SEO-04-3-M1". */
export function isMatrixTaskNumber(taskNumber?: string): boolean {
  return /^(W\d+|M)-(ACC|SEO|MED|SOC)-\d+/i.test((taskNumber || '').trim());
}

/** Identifies "the same task" even when two copies were saved under different ids. */
export function taskKey(t: Pick<TaskItem, 'taskNumber' | 'title'>): string {
  return `${(t.taskNumber || '').trim()}|${(t.title || '').trim()}`;
}
